import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"55、【豐】 離下震上","description":"橫渠易說 - 55、【豐】 離下震上","frontmatter":{"title":"55、【豐】 離下震上","description":"橫渠易說 - 55、【豐】 離下震上"},"headers":[],"relativePath":"classics/hengqu/057.md","filePath":"classics/hengqu/057.md"}'),l={name:"classics/hengqu/057.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_55、【豐】-離下震上" tabindex="-1">55、【豐】 離下震上 <a class="header-anchor" href="#_55、【豐】-離下震上" aria-label="Permalink to “55、【豐】 離下震上”">​</a></h1><p>宜日中，不宜過中也。</p><h3 id="彖曰-豐-大也-明以動-故豐。-王假之-尚大也-勿憂宜日中-宜照天下也。日中則昃-月盈則食-天地盈虛-與時消息-而況於人乎-況於鬼神乎" tabindex="-1">彖曰：豐，大也，明以動，故豐。“王假之”，尚大也；“勿憂宜日中”，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎!況於鬼神乎! <a class="header-anchor" href="#彖曰-豐-大也-明以動-故豐。-王假之-尚大也-勿憂宜日中-宜照天下也。日中則昃-月盈則食-天地盈虛-與時消息-而況於人乎-況於鬼神乎" aria-label="Permalink to “彖曰：豐，大也，明以動，故豐。“王假之”，尚大也；“勿憂宜日中”，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎!況於鬼神乎!”">​</a></h3><p>月盈則食，中弦盈之極也，此人鬼所以惡盈禍盈也。</p><h3 id="象曰-雷電皆至-豐-君子以折獄致刑。" tabindex="-1">象曰：雷電皆至，豐，君子以折獄致刑。 <a class="header-anchor" href="#象曰-雷電皆至-豐-君子以折獄致刑。" aria-label="Permalink to “象曰：雷電皆至，豐，君子以折獄致刑。”">​</a></h3><p>盛明如天，大之至也，動於上而明於下，故折獄致刑，民不惑矣。</p><h3 id="初九-遇其配主-雖旬無咎-往有尚。-象曰-雖旬無咎-過旬災也。" tabindex="-1">初九，遇其配主，雖旬無咎，往有尚。 象曰：“雖旬無咎”，過旬災也。 <a class="header-anchor" href="#初九-遇其配主-雖旬無咎-往有尚。-象曰-雖旬無咎-過旬災也。" aria-label="Permalink to “初九，遇其配主，雖旬無咎，往有尚。 象曰：“雖旬無咎”，過旬災也。”">​</a></h3><p>所之在進，光大其宜也，故往而有尚。非均是陽爻，則蔀暗之災，與六二疑疾無以異也。</p><h3 id="六二-豐其蔀-日中見鬥-往得疑疾-有孚發若-吉。-象曰-有孚發若-信以發志也。" tabindex="-1">六二，豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。 象曰：“有孚發若”，信以發志也。 <a class="header-anchor" href="#六二-豐其蔀-日中見鬥-往得疑疾-有孚發若-吉。-象曰-有孚發若-信以發志也。" aria-label="Permalink to “六二，豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。 象曰：“有孚發若”，信以發志也。”">​</a></h3><p>凡言往者，皆進而之上也。初進而上則(進)［遇］陽而有尚。二既以陰居陰而又所應亦陰，故往無所發，愈增疑疾，能不私於累，信然接物乃吉。宜日中而所應得陰，故曰“見鬥”，五在君位，故以鬥喻夜見之象。</p><h3 id="九三-豐其沛-日中見沫-折其右肱-無咎。-象曰-豐其沛-不可大事也。-折其右肱-終不可用也。" tabindex="-1">九三，豐其沛，日中見沫，折其右肱，無咎。 象曰：“豐其沛”，不可大事也。“折其右肱”，終不可用也。 <a class="header-anchor" href="#九三-豐其沛-日中見沫-折其右肱-無咎。-象曰-豐其沛-不可大事也。-折其右肱-終不可用也。" aria-label="Permalink to “九三，豐其沛，日中見沫，折其右肱，無咎。 象曰：“豐其沛”，不可大事也。“折其右肱”，終不可用也。”">​</a></h3><p>所應在陰，故曰“豐沛”。能折其右肱，絕去上六而不累其明，則可免咎也。光大之上，陰柔之終，不可用也。</p><h3 id="九四-豐其蔀-日中見鬥-遇其夷主-吉。-象曰-豐其蔀-位不當也-日中見鬥-幽不明也-遇其夷主-吉行也。" tabindex="-1">九四，豐其蔀，日中見鬥，遇其夷主，吉。 象曰：“豐其蔀”，位不當也；“日中見鬥”，幽不明也；“遇其夷主”，吉行也。 <a class="header-anchor" href="#九四-豐其蔀-日中見鬥-遇其夷主-吉。-象曰-豐其蔀-位不當也-日中見鬥-幽不明也-遇其夷主-吉行也。" aria-label="Permalink to “九四，豐其蔀，日中見鬥，遇其夷主，吉。 象曰：“豐其蔀”，位不當也；“日中見鬥”，幽不明也；“遇其夷主”，吉行也。”">​</a></h3><p>無應於下，近比於五，故亦云“見鬥”；正應亦陽，故云“夷主”。</p><h3 id="六五-來章-有慶譽-吉。-象曰-六五之吉-有慶也。" tabindex="-1">六五，來章，有慶譽，吉。 象曰：六五之吉，有慶也。 <a class="header-anchor" href="#六五-來章-有慶譽-吉。-象曰-六五之吉-有慶也。" aria-label="Permalink to “六五，來章，有慶譽，吉。 象曰：六五之吉，有慶也。”">​</a></h3><p>來章，反比陽則明也；有慶，得配於四也。</p><h3 id="上六-豐其屋-蔀其家-窺其戶-闃其無人-三歲不覿-兇。-象曰-豐其屋-天際翔也-窺其戶-闃其無人-自藏也。" tabindex="-1">上六，豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。 象曰：“豐其屋”，天際翔也；“窺其戶，闃其無人”，自藏也。 <a class="header-anchor" href="#上六-豐其屋-蔀其家-窺其戶-闃其無人-三歲不覿-兇。-象曰-豐其屋-天際翔也-窺其戶-闃其無人-自藏也。" aria-label="Permalink to “上六，豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。 象曰：“豐其屋”，天際翔也；“窺其戶，闃其無人”，自藏也。”">​</a></h3><p>豐屋蔀家，自蔽之甚，猶大明之世而夷墨其行，窮大而失居者也。處上之極，不交於下而居動之末，故曰“天際翔”也。</p>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
